import{_ as t,H as a,f as i,i as n}from"./chunks/framework.BH2BK_3i.js";const b=JSON.parse('{"title":"27 | 为什么指标数据怎么优化都不提升？","description":"","frontmatter":{},"headers":[{"level":2,"title":"传统方法为什么不灵了？","slug":"传统方法为什么不灵了","link":"#传统方法为什么不灵了","children":[]},{"level":2,"title":"以终为始打造高效的增长闭环","slug":"以终为始打造高效的增长闭环","link":"#以终为始打造高效的增长闭环","children":[{"level":3,"title":"1.指标","slug":"_1-指标","link":"#_1-指标","children":[]},{"level":3,"title":"2.假设","slug":"_2-假设","link":"#_2-假设","children":[]},{"level":3,"title":"3.分解","slug":"_3-分解","link":"#_3-分解","children":[]},{"level":3,"title":"4.实验","slug":"_4-实验","link":"#_4-实验","children":[]}]},{"level":2,"title":"复合型思维解决多样性问题","slug":"复合型思维解决多样性问题","link":"#复合型思维解决多样性问题","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]}],"relativePath":"从0开始做增长/27-为什么指标数据怎么优化都不提升？.md","filePath":"从0开始做增长/27-为什么指标数据怎么优化都不提升？.md","lastUpdated":1779818163000}'),s={name:"从0开始做增长/27-为什么指标数据怎么优化都不提升？.md"};function r(l,e,p,o,h,c){return a(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="_27-为什么指标数据怎么优化都不提升" tabindex="-1">27 | 为什么指标数据怎么优化都不提升？ <a class="header-anchor" href="#_27-为什么指标数据怎么优化都不提升" aria-label="Permalink to &quot;27 | 为什么指标数据怎么优化都不提升？&quot;">​</a></h1><p>你好，我是刘津。</p><p>结束了前面的增长方向和增长策略的内容，今天我们开始学习落地执行方面的知识，也正式进入了第四个模块：打造百发百中的增长闭环。</p><p>说到“百发百中”，你可能会怀疑，真的有这么神奇吗？现实工作中遇到的经常是数据怎么优化都不提升的情况吧。</p><h2 id="传统方法为什么不灵了" tabindex="-1">传统方法为什么不灵了？ <a class="header-anchor" href="#传统方法为什么不灵了" aria-label="Permalink to &quot;传统方法为什么不灵了？&quot;">​</a></h2><p>其实只要方法对了， <strong>“百发百中”的增长是可以成为常态的</strong>。你之所以觉得这很不可思议，是因为我们传统的工作方法并不是以增长为目的，而是以改进问题为目的。</p><p>这就是我前面说过的“正向”和“负向”。</p><p>传统工作方式更多在于解决问题，也就是“负向”为主。而创新和增长更重要的是解决“正向”的问题，即通过洞察发现差异化的优势，带来四两拨千斤的增长效果。这可比单纯的改进问题含金量高多了，自然价值也大得多。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BB%8E0%E5%BC%80%E5%A7%8B%E5%81%9A%E5%A2%9E%E9%95%BF/images/100281/d90cdf0b7078135018bb87a86dc94ca3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BB%8E0%E5%BC%80%E5%A7%8B%E5%81%9A%E5%A2%9E%E9%95%BF/images/100281/d90cdf0b7078135018bb87a86dc94ca3.png" alt=""></a></p><p>我们先来看看传统流程。</p><p>首先，是发现问题，这里包括用户反馈的问题、业务提出的问题、技术bug等等。罗列出各种问题后，把这些问题做个归类，归纳出几类重点。然后围绕这几项重点提出改进建议。落地执行后，再看数据反馈情况。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BB%8E0%E5%BC%80%E5%A7%8B%E5%81%9A%E5%A2%9E%E9%95%BF/images/100281/8c33863aba44d0d57f1f8464d8eac112.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BB%8E0%E5%BC%80%E5%A7%8B%E5%81%9A%E5%A2%9E%E9%95%BF/images/100281/8c33863aba44d0d57f1f8464d8eac112.png" alt=""></a></p><p>这就是传统的解决问题的思路，虽然看上去无懈可击，却并不高效。</p><p>就像我在前面内容里不断提到的：我们并非要面面俱到地解决所有问题，也不是要把自认为最好最专业的带给用户；而是通过差异性洞察，在千头万绪中找到最关键的足以影响到增长的爆破点。</p><p>所以，传统工作方式耗时耗力，却未必能带来关键指标的提升，就是这个道理。大部分人都在急着填补目前的漏洞，不是在优化功能、性能，就是在追赶竞品，每天都在“救火”。但如果沉下心来想想更关键的起决定性作用的事情，你也许就能出奇制胜。</p><h2 id="以终为始打造高效的增长闭环" tabindex="-1">以终为始打造高效的增长闭环 <a class="header-anchor" href="#以终为始打造高效的增长闭环" aria-label="Permalink to &quot;以终为始打造高效的增长闭环&quot;">​</a></h2><p>既然传统的工作方式存在弊端，那我们应该如何改变呢？这里给你介绍一个新的思路，我把它称为“精益闭环”。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BB%8E0%E5%BC%80%E5%A7%8B%E5%81%9A%E5%A2%9E%E9%95%BF/images/100281/03220317623bcd9e880b032b67bf1771.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BB%8E0%E5%BC%80%E5%A7%8B%E5%81%9A%E5%A2%9E%E9%95%BF/images/100281/03220317623bcd9e880b032b67bf1771.png" alt=""></a></p><p>精益闭环秉承了“以用户为中心增长”的核心理念。“以用户为中心增长”我想你已经不陌生了，就是通过深入的用户洞察找到用户最关心的、最能带来增长的爆点。此外，再结合增长黑客最爱的增长思维，即“数据驱动+低成本快速实验”，形成新的工作流程。</p><p>精益闭环分为四个步骤，分别是：指标、假设、分解、实验。</p><h3 id="_1-指标" tabindex="-1">1.指标 <a class="header-anchor" href="#_1-指标" aria-label="Permalink to &quot;1.指标&quot;">​</a></h3><p>指标主要是通过北极星指标分解得来的。具体可参考用户增长地图中的关键指标。当然，也需要考虑具体场景。比如首页改版，既需要考虑用户旅程中对应的关键指标（比如转化率），也需要考虑和首页相关的指标（比如跳出率）。</p><h3 id="_2-假设" tabindex="-1">2.假设 <a class="header-anchor" href="#_2-假设" aria-label="Permalink to &quot;2.假设&quot;">​</a></h3><p>假设是通过洞察得到的可能提升指标的方式。从指标到假设，可以帮助我们避免做太多无用功，而是专注在与增长相关的关键问题上。</p><p>举个例子，有个朋友想改进一个营销落地页面，通过头脑风暴大家一起提出了10项改进建议，他问我这样是否可以？我问他这个页面的指标是什么，他说是提升转化率。我又问这10项改进建议，哪些和提升转化有关，他看了一下，说只有2个。这样就可以优先做这两个改进，剩下的8个往后排排。</p><h3 id="_3-分解" tabindex="-1">3.分解 <a class="header-anchor" href="#_3-分解" aria-label="Permalink to &quot;3.分解&quot;">​</a></h3><p>每条假设都可以分解成若干个变量，有助于量化结果。之所以要再分解，是因为我们做的很多工作都未必能带来关键指标的提升，这让我们误以为很多东西是难以被量化的，尤其是偏创意、设计类的工作。但其实只要学会科学的分解，任何事情都是可以被量化的。</p><p>你还记得曹冲称象的故事吗？大象很大，但是秤很小，所以无法称量大象的体重。但是曹冲想了个很聪明的方法，把大象转换成同重量的石块，然后一一称量石块的重量，再累加就可以了。这不就是“分解”后量化的一个极佳的例子吗？</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BB%8E0%E5%BC%80%E5%A7%8B%E5%81%9A%E5%A2%9E%E9%95%BF/images/100281/b2ca1fb41521fbcaa1895f2acaf63a3c.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BB%8E0%E5%BC%80%E5%A7%8B%E5%81%9A%E5%A2%9E%E9%95%BF/images/100281/b2ca1fb41521fbcaa1895f2acaf63a3c.png" alt=""></a></p><p>所以，当我们无法验证数据结果，或数据结果不好的时候，我们就可以通过分解去探寻究竟，看看到底做什么事情会带来数据提升，做什么事情会导致数据下降。这样就把增长从偶然、撞大运变成了一件常规的事情。</p><p>举个例子，假设你做了一次大改版，数据没有提升，这是因为在这次改版中你做的事情实在太多了。你可能改进了100个地方，其中50个地方带来了提升，50个地方导致了下降，最终就互相抵消了。但是，如果你把完整的方案拆成100个变量，再去一一的看，你自然就知道哪个改进效果好，哪个改进效果不好，那么增长也就是板上钉钉的事情了。</p><p>通过分解，我们 <strong>验证的结果可以被不断复用</strong>。</p><p>比如，你发现蓝色比红色效果好，A文案比B文案好等等，这些结论都是可以被复用到其它页面或类似的产品上的。但是如果用的是传统方式，你就无法判断出是因为什么导致了最后的结果好还是不好，所以也很难复用，这当然是十分低效的。</p><h3 id="_4-实验" tabindex="-1">4.实验 <a class="header-anchor" href="#_4-实验" aria-label="Permalink to &quot;4.实验&quot;">​</a></h3><p>在经过指标、假设、分解这三个步骤后，我们需要通过实验结果来验证每一个被测试的变量的效果。这里面会涉及到一些较专业的统计方面的知识，我在下一个模块会专门介绍。</p><p>实验的结果自然有好有坏，好的结果我们可以不断复用，不好的结果我们以后可以尽量避免。所以 <strong>每一次的结果都是非常有价值的</strong>。</p><p>通过指标、假设、分解、实验，看实验结果是否提升了指标，形成了一个“以终为始”的闭环。“闭环”这个词你肯定不会陌生，现在很多商业大佬都在讲闭环，因为闭环是最高效的。</p><p>说到“以终为始”，我想举个例子来为你说明。</p><p>前几天，我参加了一个作者交流会，有幸听了知名畅销书作家李笑来老师的分享。他说，如果你想写一本畅销10年的书，你一定要先问问自己：这本书10年以后还会有人愿意看吗？如果答案是否定的，那他就不写。这不就是“以终为始”的思路吗？也就是你做一件事情之前，先想想你希望产生什么样的结果，然后再把这个结果作为目标倒推出你要做什么事情。</p><p>后来他又说，你想让你的书畅销，那你一定要找差异化，看看自己的内容和其他人的内容有什么区别，优势在哪里？比如，别人都在谈时间管理，而他在书里却提出了“时间是不可被管理”的新思想。这不就是我之前说的“差异化洞察”吗？所以说，做产品也好，做人也好，写书也好，道理都是一样的。</p><p>在实际工作中，精益闭环能引导我们找到可量化的与产品核心价值相关的指标；并以此为方向找到提升指标的假设，避免做无用功；再通过分解明确导致数据提升的原因，并且可持续复用；最重要的是，它能够驱动创新，改变了我们寻找问题、改进缺陷的旧有思路，而是把更多精力放在更直接的创造价值的事情上。</p><h2 id="复合型思维解决多样性问题" tabindex="-1">复合型思维解决多样性问题 <a class="header-anchor" href="#复合型思维解决多样性问题" aria-label="Permalink to &quot;复合型思维解决多样性问题&quot;">​</a></h2><p>精益闭环的思路不限产品阶段、不限优化对象、也不限产品、运营、设计等职能限制。它甚至可以帮你解决重要的人生决策问题。</p><p>它之所以能如此通用，是因为本质上它是跨界产物，它既包含了增长思维，又包含了精益思维，还有创新思维和敏捷思维。而 <strong>做增长，恰恰需要结合多种思维，融会贯通。</strong></p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BB%8E0%E5%BC%80%E5%A7%8B%E5%81%9A%E5%A2%9E%E9%95%BF/images/100281/271138fee720f42f40e201f92abd496b.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BB%8E0%E5%BC%80%E5%A7%8B%E5%81%9A%E5%A2%9E%E9%95%BF/images/100281/271138fee720f42f40e201f92abd496b.png" alt=""></a></p><p>在下一讲，我会为你讲解我工作中遇到的实际案例。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BB%8E0%E5%BC%80%E5%A7%8B%E5%81%9A%E5%A2%9E%E9%95%BF/images/100281/13692e5cbdbc663238def75f6aef0af5.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BB%8E0%E5%BC%80%E5%A7%8B%E5%81%9A%E5%A2%9E%E9%95%BF/images/100281/13692e5cbdbc663238def75f6aef0af5.png" alt=""></a></p><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><p>审视一下你过去的工作方式，看看是查缺补漏的情况多，还是创新、抓重点的情况多呢？</p><p>欢迎把你的思考和疑问通过留言分享出来，与我和其他同学一起讨论。如果你觉得有所收获，也欢迎把文章分享给你的朋友。</p>',50)])])}const g=t(s,[["render",r]]);export{b as __pageData,g as default};
